CREATE TABLE IF NOT EXISTS inspections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL,scheduled_for DATE NOT NULL,checklist JSONB NOT NULL CHECK(jsonb_array_length(checklist)>0),findings JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN('SCHEDULED','COMPLETED','CANCELLED')),passed BOOLEAN NOT NULL,reinspection_of_id UUID REFERENCES inspections(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS issue_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL,kind TEXT NOT NULL CHECK(kind IN('ISSUE','RISK')),severity TEXT NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH','CRITICAL')),description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('OPEN','ESCALATED','CAPA_IN_PROGRESS','RESOLVED','CLOSED')),raised_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),escalated_at TIMESTAMPTZ,resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS corrective_action_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),issue_id UUID NOT NULL REFERENCES issue_records(id),action_plan TEXT NOT NULL,owner_id UUID NOT NULL,due_date DATE NOT NULL,status TEXT NOT NULL CHECK(status IN('OPEN','COMPLETED','VERIFIED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS change_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL,milestone_id UUID NOT NULL,change_type TEXT NOT NULL CHECK(change_type IN('SCOPE','SCHEDULE','COST','ACCEPTANCE_CRITERIA','EVIDENCE_REQUIREMENT','PAYMENT_TRIGGER')),description TEXT NOT NULL,impact JSONB NOT NULL,requested_by UUID NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','SUBMITTED','APPROVED','REJECTED','IMPLEMENTED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS change_approvals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),change_request_id UUID NOT NULL REFERENCES change_requests(id),approver_id UUID NOT NULL,decision TEXT NOT NULL CHECK(decision IN('APPROVE','REJECT')),rationale TEXT NOT NULL,decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS acceptance_decisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL,decision TEXT NOT NULL CHECK(decision IN('FULL','PARTIAL','CONDITIONAL','PROVISIONAL','REJECTED','DEFERRED')),rationale TEXT NOT NULL,conditions JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN('ACTIVE','SUPERSEDED')),decided_by UUID NOT NULL,decided_at TIMESTAMPTZ NOT NULL DEFAULT now(),supersedes_id UUID REFERENCES acceptance_decisions(id));
CREATE TABLE IF NOT EXISTS completion_certificates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL,milestone_id UUID NOT NULL,certificate_number TEXT NOT NULL UNIQUE,acceptance_decision_id UUID NOT NULL REFERENCES acceptance_decisions(id),canonical_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('CERTIFIED','REVOKED')),issued_by UUID NOT NULL,issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),revoked_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS inspections_work_item_idx ON inspections(workspace_id,work_item_id);CREATE INDEX IF NOT EXISTS issue_records_work_item_status_idx ON issue_records(workspace_id,work_item_id,status);CREATE INDEX IF NOT EXISTS change_requests_milestone_idx ON change_requests(workspace_id,milestone_id);CREATE INDEX IF NOT EXISTS acceptance_decisions_work_item_idx ON acceptance_decisions(workspace_id,work_item_id,status);CREATE INDEX IF NOT EXISTS completion_certificates_work_item_idx ON completion_certificates(workspace_id,work_item_id);
ALTER TABLE inspections ENABLE ROW LEVEL SECURITY;ALTER TABLE issue_records ENABLE ROW LEVEL SECURITY;ALTER TABLE corrective_action_plans ENABLE ROW LEVEL SECURITY;ALTER TABLE change_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE change_approvals ENABLE ROW LEVEL SECURITY;ALTER TABLE acceptance_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE completion_certificates ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['inspections','issue_records','corrective_action_plans','change_requests','change_approvals','acceptance_decisions','completion_certificates'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['inspections','change_approvals','acceptance_decisions','completion_certificates'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
